`timescale 1ns/1ps
// Auto-generated by autombist from config.yml: a BEHAVIORAL model of the memory,
// inputs registered on the rising clock edge, the write and the read done on the falling edge (read_latency 0).
// Idealized: fault-free, no timing checks, contents power up unknown. It is NOT the
// macro's own model; pass that model to run_tb.sh to replace this one.
// Column-muxed, 4 words per row: each spare lane is one cell per physical
// row, shared by the row's words and kept at its first address (OpenRAM's layout).
module sram_s2dmux #(
    parameter integer ADDR_WIDTH = 4,
    parameter integer DATA_WIDTH = 8,
    parameter integer NUM_SPARE_ROWS = 1,
    parameter integer NUM_SPARE_COLS = 2
) (
    input  wire clk0,
    input  wire csb0,
    input  wire web0,
    input  wire [4:0] addr0,
    input  wire [9:0] din0,
    input  wire [1:0] spare_wen0,
    output reg  [9:0] dout0
);
    // The wrapper overrides the parameters above; the widths below are the ones it connects.
    localparam integer LOGICAL_W = 8;
    localparam integer DEPTH = 32;
    reg [9:0] mem [0:DEPTH-1];

    // The word at a: its logical bits from mem[a], its spare lanes from the row's
    // first address, the one spare cell its physical row has.
    function [9:0] word_at(input [4:0] a);
        reg [4:0] b;
        reg [9:0] w, s;
        begin
            b = {a[4:2], 2'b0};
            w = mem[a];
            s = mem[b];
            word_at = {s[9:LOGICAL_W], w[LOGICAL_W-1:0]};
        end
    endfunction

    // port 0: rw
    reg p0_csb_q;
    reg [4:0] p0_addr_q;
    reg p0_we_q;
    reg [9:0] p0_din_q;
    reg [1:0] p0_spare_q;
    integer p0_k;
    always @(posedge clk0) begin
        p0_csb_q  <= csb0;
        p0_addr_q <= addr0;
        p0_we_q   <= web0;
        p0_din_q  <= din0;
        p0_spare_q <= spare_wen0[1:0];
    end
    always @(negedge clk0) begin
        if (!p0_csb_q && !p0_we_q) begin
            mem[p0_addr_q][LOGICAL_W-1:0] <= p0_din_q[LOGICAL_W-1:0];
            for (p0_k = 0; p0_k < 2; p0_k = p0_k + 1)
                if (p0_spare_q[p0_k]) mem[{p0_addr_q[4:2], 2'b0}][LOGICAL_W + p0_k] <= p0_din_q[LOGICAL_W + p0_k];
        end
        if (!p0_csb_q && p0_we_q) dout0 <= word_at(p0_addr_q);
    end

endmodule
